import subprocess
import ftplib
import os


def task_func(ftp_server='ftp.dlptest.com', ftp_user='dlpuser', ftp_password='rNrKYTX9g7z3RgJRmxWuGHbeu', ftp_dir='/ftp/test'):
    """
    Download all files from a specific directory on an FTP server using
    wget in a subprocess.

    Args:
        ftp_server (str): The FTP server address.
        ftp_user (str): The FTP server username.
        ftp_password (str): The FTP server password.
        ftp_dir (str): The directory on the FTP server to download from.

    Returns:
        List[str]: The filenames that were attempted to be downloaded.

    Raises:
        Exception: If connecting to the server fails.
        Exception: If logging into the server fails.
        Exception: If changing to the requested directory fails.
    """
    ftp = ftplib.FTP()

    try:
        try:
            ftp.connect(ftp_server)
        except Exception as e:
            raise Exception(
                f"Failed to connect to FTP server {ftp_server}: {str(e)}"
            )

        try:
            ftp.login(ftp_user, ftp_password)
        except Exception as e:
            raise Exception(
                f"Failed to log into FTP server {ftp_server} with user {ftp_user}: {str(e)}"
            )

        try:
            ftp.cwd(ftp_dir)
        except Exception as e:
            raise Exception(
                f"Failed to change to directory {ftp_dir} on server {ftp_server}: {str(e)}"
            )

        # Fetch the directory listing; nothing can be attempted without one.
        try:
            entries = ftp.nlst()
        except Exception:
            entries = []

        base_dir = ftp_dir.rstrip('/')
        attempted = []

        for entry in entries or []:
            if entry in ('.', '..'):
                continue

            filename = os.path.basename(str(entry).rstrip('/'))
            if not filename or filename in ('.', '..'):
                continue

            url = (
                f"ftp://{ftp_user}:{ftp_password}@{ftp_server}"
                f"{base_dir}/{filename}"
            )
            attempted.append(filename)

            # A failed wget invocation (including a missing binary) must not
            # stop the remaining downloads, so individual errors are ignored.
            try:
                subprocess.run(['wget', url], capture_output=True)
            except Exception:
                pass

        return attempted
    finally:
        try:
            ftp.quit()
        except Exception:
            try:
                ftp.close()
            except Exception:
                pass
